<form method="post" id="inventory-form"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="revision" value="<?=h(bmu_revision($data))?>"><input type="hidden" name="building_revision" value="<?=h(bmu_revision($locations))?>"><input type="hidden" name="inventory" id="inventory"><section><input type="hidden" id="state" value="unknown"><fieldset class="presence"><legend>건물에 다중이용업소가 있나요?</legend><div class="presence-options"><label><input type="radio" name="presence" value="present"><span><b>있음</b><small>업소 정보 입력하기</small></span></label><label><input type="radio" name="presence" value="none"><span><b>없음</b><small>계획서에 없음으로 반영</small></span></label></div></fieldset><p id="presence-note" role="status">있음 또는 없음을 선택해 주세요.</p><small>다중이용업소 유무를 확인한 뒤, 있는 경우 업소명·업종·영업층을 입력하세요.</small></section><div id="details" hidden><div id="rows"></div><button type="button" id="add" class="secondary">＋ 업소 추가</button><p id="empty" class="empty">업소를 추가하고 정보를 입력해 주세요.</p></div><input type="hidden" name="form_end" value="1"><div class="bar"><small>저장한 현황은 소방계획서 별첨에 반영됩니다.</small><button type="submit">저장하기</button></div></form></main>
<script>
(()=>{'use strict';const locations=<?=json_encode($locations,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE)?>,types=<?=json_encode(bmu_types(),JSON_UNESCAPED_UNICODE)?>,initial=<?=json_encode($error?($input??$data):$data,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE)?>;const list=document.getElementById('rows'),state=document.getElementById('state');state.value=initial.state||'unknown';
function option(value,label){const o=document.createElement('option');o.value=value;o.textContent=label;return o;}
function add(row={}){if(list.children.length>=100)return;state.value='present';const card=document.createElement('section');card.dataset.id=row.id||'';const head=document.createElement('header'),title=document.createElement('h2'),remove=document.createElement('button');title.textContent=row.name||'새 업소';remove.type='button';remove.className='remove';remove.textContent='삭제';remove.onclick=()=>{if(confirm('이 업소를 목록에서 삭제할까요? 저장하기를 눌러 반영합니다.')){card.remove();empty();}};head.append(title,remove);card.append(head);const grid=document.createElement('div');grid.className='grid';card.append(grid);
function field(key,label,choices){const wrap=document.createElement('label');wrap.textContent=label;const el=document.createElement(choices?'select':'input');el.dataset.field=key;if(choices)choices.forEach(v=>el.append(option(v,v)));else el.maxLength=['facilities','note'].includes(key)?500:200;el.value=row[key]||'';wrap.append(el);grid.append(wrap);return el;}
const name=field('name','업소명 *');name.required=true;name.oninput=()=>title.textContent=name.value||'새 업소';field('type','업종 *',['',...types]).required=true;
const dong=field('dong','입점 동 *',[]);Object.entries(locations).forEach(([k,l])=>dong.append(option(k,l.name)));dong.value=row.dong||Object.keys(locations)[0]||'';dong.parentElement.hidden=Object.keys(locations).length===1;const floors=document.createElement('fieldset');floors.className='floor-picker';floors.dataset.floors='1';const legend=document.createElement('legend');legend.textContent='영업층';const hint=document.createElement('small');hint.className='floor-hint';hint.textContent='업소가 사용하는 범위를 선택하세요';const modes=document.createElement('div');modes.className='floor-modes';const all=document.createElement('button'),partial=document.createElement('button');all.type=partial.type='button';all.textContent=Object.keys(locations).length>1?'선택한 동 전체 사용':'건물 전체 사용';partial.textContent='일부 층 사용';modes.append(all,partial);const chips=document.createElement('div');chips.className='floor-chips';const summary=document.createElement('p');summary.className='floor-summary';summary.setAttribute('aria-live','polite');floors.append(legend,hint,modes,chips,summary);grid.append(floors);function selectedSummary(){const chosen=[...chips.querySelectorAll('input:checked')].map(el=>el.dataset.label);summary.textContent=all.getAttribute('aria-pressed')==='true'?'전체 층 사용 · '+chosen.join(', '):chosen.length?'선택한 층 · '+chosen.join(', '):'사용하는 층을 아래에서 선택해 주세요';floors.classList.remove('has-error');}
function refresh(selected=[]){chips.replaceChildren();const options=Object.entries(locations[dong.value]?.floors||{});options.forEach(([k,l])=>{const label=document.createElement('label'),input=document.createElement('input'),text=document.createElement('span'),check=document.createElement('span');input.type='checkbox';input.value=k;input.dataset.label=l;input.checked=selected.includes(k);input.onchange=selectedSummary;text.textContent=l.replace('지상 ','').replace('지하 ','B').replace('층','')+(k.startsWith('B')?'':'층');check.className='floor-check';check.textContent='✓';check.setAttribute('aria-hidden','true');input.setAttribute('aria-label',l);label.append(input,check,text);chips.append(label);});selectedSummary();if(!options.length)summary.textContent='기본정보에서 층수를 먼저 입력해 주세요.';}
function mode(entire){all.setAttribute('aria-pressed',String(entire));partial.setAttribute('aria-pressed',String(!entire));chips.hidden=entire;chips.querySelectorAll('input').forEach(el=>{if(entire)el.checked=true;});selectedSummary();}all.onclick=()=>mode(true);partial.onclick=()=>{if(all.getAttribute('aria-pressed')==='true')chips.querySelectorAll('input').forEach(el=>el.checked=false);mode(false);};refresh(row.floors||[]);const available=[...chips.querySelectorAll('input')];mode(available.length>0&&available.every(el=>el.checked));dong.onchange=()=>{const entire=all.getAttribute('aria-pressed')==='true';refresh();mode(entire);};list.append(card);empty();presence();}
function empty(){document.getElementById('empty').hidden=!!list.children.length;}
function presence(){const yes=state.value==='present';document.getElementById('details').hidden=!yes;document.querySelectorAll('input[name=presence]').forEach(r=>r.checked=r.value===state.value);list.querySelectorAll('input,select').forEach(el=>el.disabled=!yes);document.getElementById('presence-note').textContent=state.value==='none'?'저장하면 소방계획서 별첨에 ‘다중이용업소 없음’으로 반영됩니다. 기존 업소 내역은 제외됩니다.':yes?'아래에서 업소별 정보를 입력해 주세요.':'있음 또는 없음을 선택해 주세요.';}
(initial.rows||[]).forEach(add);state.value=initial.state||'unknown';empty();presence();document.querySelectorAll('input[name=presence]').forEach(r=>r.onchange=()=>{state.value=r.value;if(r.value==='present'&&!list.children.length)add();presence();});document.getElementById('add').onclick=()=>add();document.getElementById('inventory-form').onsubmit=e=>{if(state.value==='unknown'){e.preventDefault();document.getElementById('presence-note').textContent='있음 또는 없음을 먼저 선택해 주세요.';return;}if(state.value==='present'){const missing=[...list.querySelectorAll('[data-floors]')].find(group=>!group.querySelector('input:checked'));if(missing){e.preventDefault();missing.classList.add('has-error');missing.querySelector('.floor-summary').textContent='영업층을 한 개 이상 선택해 주세요.';missing.scrollIntoView({block:'center',behavior:'smooth'});missing.querySelector('input')?.focus({preventScroll:true});return;}}const rows=(state.value==='present'?[...list.children]:[]).map(card=>{const r={id:card.dataset.id,floors:[...card.querySelectorAll('[data-floors] input:checked')].map(el=>el.value)};card.querySelectorAll('[data-field]').forEach(el=>r[el.dataset.field]=el.multiple?[...el.selectedOptions].map(o=>o.value):el.value);return r;});document.getElementById('inventory').value=JSON.stringify({state:state.value,rows});};
})();
</script></body></html>
